def paragraph_for(n):
    if 736 <= n <= 738: return 11
    if 739 <= n <= 782: return 12
    if 783 <= n <= 802: return 13
    if 803 <= n <= 819: return 14
    if n in {839,852}: return 16
    if 840 <= n <= 844: return 15
    if 836 <= n <= 838 or 845 <= n <= 865: return 17
    if 876 <= n <= 900: return 22
    if 918 <= n <= 920: return 23
    if 921 <= n <= 947: return 26
    return 12

def topic_for(n):
    p=paragraph_for(n)
    return {
        11:'Удельная теплоёмкость',12:'Количество теплоты и тепловой баланс',13:'Энергия топлива',14:'Закон сохранения энергии',
        15:'Плавление и отвердевание',16:'График плавления и отвердевания',17:'Удельная теплота плавления',
        22:'Парообразование и конденсация',23:'Работа газа и тепловые процессы',26:'КПД теплового двигателя'
    }[p]

def type_for(n, text):
    if n in {839,852}: return 'graph'
    starts = ('Почему','Что ','В каком','Будет ли','Каким ','Какой энергией','Какие превращения','За счет','Одинаково ли','Сравните')
    if text.startswith(starts): return 'qualitative'
    return 'calculation'

old = json.loads(TASKS.read_text(encoding='utf-8'))
old = [t for t in old if not str(t.get('ID','')).startswith('genius-peryshkin-')]
